WITH cleaned AS (SELECT id, method, amount, status, ROUND(amount, 2) amount_rounded, COALESCE(method, 'N/A') resolved_method FROM payments WHERE method IS NOT NULL), latest AS (SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY amount_rounded, id) = 1), scored AS (SELECT id, method, amount, status, amount_rounded, resolved_method, NTILE(5) OVER w_part amount_bucket, LEAD(amount, 2) OVER w_part_2 next_amount FROM latest WINDOW w_part AS (PARTITION BY status, method ORDER BY amount, id), w_part_2 AS (PARTITION BY method, status ORDER BY amount, id)), by_type AS (SELECT * FROM (SELECT method, status, amount FROM scored) src PIVOT (MAX(amount) AS amount FOR status IN ('FAILED' AS failed, 'REFUNDED' AS refunded))) SELECT method FROM by_type ORDER BY method NULLS LAST
